export function slugify(input) {
  // 原因：原实现只把空白替换为连字符，标点未处理且首尾会留下连字符；
  // 修复：先把连续的非 ASCII 字母数字归一为一个连字符，再裁掉首尾连字符。
  return String(input)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
